import re, html
for name in ['sbir_news', 'sbir_apply']:
    raw = open(f'/tmp/{name}.html', encoding='utf-8', errors='ignore').read()
    text = re.sub(r'<script.*?</script>|<style.*?</style>', ' ', raw, flags=re.S)
    # extract links with titles
    print(f'===== {name} =====')
    if name == 'sbir_news':
        for m in re.finditer(r'<a[^>]+href="([^"]*(?:main_content|other_content)[^"]*)"[^>]*>(.*?)</a>', text, re.S):
            title = html.unescape(re.sub(r'<[^>]+>', '', m.group(2))).strip()
            if title:
                print(m.group(1), '|', title[:120])
    else:
        t = html.unescape(re.sub(r'<[^>]+>', '\n', text))
        lines = [l.strip() for l in t.split('\n') if l.strip()]
        # print lines around keywords
        for i, l in enumerate(lines):
            if re.search(r'受理|截止|梯次|申請期間|收件', l):
                print(' | '.join(lines[max(0,i-1):i+3])[:300])
EOF
